(function($) {
	//----------------------------------------
	// Hamburger
	//----------------------------------------

	$(".hamburger").click(function(){
		$('.hamburger').toggleClass('is-active');
		$('header').toggleClass('is-active');
		$('#header_nav').toggleClass('open');
		$('#header_nav').slideToggle('fast');
	});

	//----------------------------------------
	// Nested Accordion Navigation
	//----------------------------------------

	$('li.menu-item-has-children a').on("click", function(e){
		e.stopPropagation();
		e.preventDefault();
		if($(this).parents('.menu-item-has-children').length < 2){
			$(".sub-menu").slideUp(50);
		}
		if(!$(this).closest('li').hasClass('menu-item-has-children')){
			window.location.href = $(this).attr('href');
		}
		$(this).next('.sub-menu').slideToggle(50);
	});

	$("body").click(function () {
		$(".sub-menu").slideUp(50);
	});

	//----------------------------------------
	// Smooth Scroll
	//----------------------------------------

	$("a").on('click', function(event) {
		if (this.hash !== "") {
		event.preventDefault();

		var hash = this.hash;

		$('html, body').animate({
			scrollTop: $(hash).offset().top
			}, 800, function(){
				window.location.hash = hash;
			});
		}
	});

	//----------------------------------------
	// Format Phone Numbers
	//----------------------------------------

	$('input[type="tel"]').keyup(function() {
		var val = this.value.replace(/\D/g, '');
		var newVal = '';
		for (var i = 0; i < 2; i++) {
			if (val.length > 3) {
				newVal += val.substr(0, 3) + '-';
				val = val.substr(3);
			}
		}
		newVal += val;
		this.value = newVal;
	});

	// Find all div elements with the class "phone"
	const phoneDivs = document.querySelectorAll('.phone');
	// Iterate over each div and format the phone number
	phoneDivs.forEach((div) => {
	  // Get the raw phone number from the div's text content
	  const rawPhoneNumber = div.textContent.trim();
	  // Check if the raw phone number contains exactly 10 digits
	  if (rawPhoneNumber.length === 10) {
		// Format the phone number as (555) 555-555
		const formattedPhoneNumber = `(${rawPhoneNumber.slice(0, 3)}) ${rawPhoneNumber.slice(3, 6)}-${rawPhoneNumber.slice(6)}`;
		// Update the div's text content with the formatted phone number
		div.textContent = formattedPhoneNumber;
	  }
	});

	//----------------------------------------
	// Orphans
	//----------------------------------------

	// Function to replace space with &nbsp; between last and second to last words
	function fixSpaceInClass(className) {
		var elements = document.querySelectorAll('.' + className);

		elements.forEach(function(element) {
			var content = element.innerHTML.trim();
			var words = content.split(' ');

			if (words.length >= 2) {
				var lastWord = words.pop();
				var secondToLastWord = words.pop();
				var modifiedContent = words.join(' ') + ' ' + secondToLastWord + '&nbsp;' + lastWord;
				element.innerHTML = modifiedContent;
			}
		});
	}

	// Specify your CSS classes here
	var classesToFix = [
		'no-orphans',
		'page__title',
		'footer__col--about p',
		'wp-block-latest-posts__post-title',
		'section__title',
		'plan__step-subtitle',
		'testimonials__quote',
		'aside wp-block-heading'
	];

	// Apply the function to each specified class
	classesToFix.forEach(function(className) {
		fixSpaceInClass(className);
	});

		//----------------------------------------
	// Language Switcher Dropdown
	//----------------------------------------

	$('.language-switcher__trigger').on('click', function(e) {
		e.preventDefault();
		e.stopPropagation();

		const $trigger = $(this);
		const $dropdown = $trigger.next('.language-switcher__dropdown-menu');
		const isExpanded = $trigger.attr('aria-expanded') === 'true';

		// Close all other language switchers
		$('.language-switcher__trigger').not($trigger).attr('aria-expanded', 'false');
		$('.language-switcher__dropdown-menu').not($dropdown).attr('aria-hidden', 'true');

		// Toggle current dropdown
		if (isExpanded) {
			$trigger.attr('aria-expanded', 'false');
			$dropdown.attr('aria-hidden', 'true');
		} else {
			$trigger.attr('aria-expanded', 'true');
			$dropdown.attr('aria-hidden', 'false');
		}
	});

	// Close dropdown when clicking outside
	$(document).on('click', function(e) {
		if (!$(e.target).closest('.language-switcher').length) {
			$('.language-switcher__trigger').attr('aria-expanded', 'false');
			$('.language-switcher__dropdown-menu').attr('aria-hidden', 'true');
		}
	});

	// Close dropdown when pressing Escape key
	$(document).on('keydown', function(e) {
		if (e.key === 'Escape') {
			$('.language-switcher__trigger').attr('aria-expanded', 'false');
			$('.language-switcher__dropdown-menu').attr('aria-hidden', 'true');
		}
	});

	//----------------------------------------
	// Partners Archive Tab Switching
	//----------------------------------------
	// Both sectors (government + private) are preloaded in the HTML by the
	// block template. Switching tabs just toggles visibility — instant, no AJAX.
	// Pagination within each sector still uses AJAX for pages > 1 (handled by
	// the inline initPag script in block-partners-archive.php).

	function initPartnersArchiveTabs() {
		const tabs = document.querySelectorAll('.partners__tab');
		if (!tabs.length) return;

		tabs.forEach(tab => {
			tab.addEventListener('click', function() {
				const sector = this.getAttribute('data-sector');

				// Update active tab
				tabs.forEach(t => t.classList.remove('partners__tab--active'));
				this.classList.add('partners__tab--active');

				// Toggle grids: hide all, show the one matching the sector
				document.querySelectorAll('.partners-archive__grid').forEach(grid => {
					grid.style.display = (grid.getAttribute('data-sector') === sector) ? '' : 'none';
				});

				// Toggle pagination navs the same way.
				// A nav is shown only if it belongs to the active sector AND has > 1 page.
				document.querySelectorAll('.partners-archive__pagination').forEach(nav => {
					if (nav.getAttribute('data-sector') !== sector) {
						nav.style.display = 'none';
						return;
					}
					const total = parseInt(nav.dataset.total, 10) || 1;
					nav.style.display = total > 1 ? '' : 'none';
				});
			});
		});
	}

	// Initialize on DOM ready
	if (document.readyState === 'loading') {
		document.addEventListener('DOMContentLoaded', initPartnersArchiveTabs);
	} else {
		initPartnersArchiveTabs();
	}

})( jQuery );
